input.command:
Write-Output "=== Port 4310 ==="; Get-NetTCPConnection -LocalPort 4310 -ErrorAction SilentlyContinue | Select-Object LocalAddress,LocalPort,State,OwningProcess | Format-Table -AutoSize
Write-Output "=== node processes ==="; Get-Process node -ErrorAction SilentlyContinue | Select-Object Id,StartTime,@{n='CPU(s)';e={[math]::Round($_.CPU,1)}},Path | Format-Table -AutoSize
Write-Output "=== HTTP probe ==="; try { $r = Invoke-WebRequest -Uri "http://localhost:4310" -UseBasicParsing -TimeoutSec 5; "Status: $($r.StatusCode)  Length: $($r.RawContentLength)" } catch { "ERR: $($_.Exception.Message)" }
